-- 0139 — Textbooks (NCERT catalogue links + a school's own mapping) and
-- curriculum materials (the school's own uploaded files).
--
-- Legal ruling (owner, 2026-11-11): NCERT lets its books be downloaded free
-- "for non-commercial purposes" and gives no permission to private parties.
-- This product is commercial, so the catalogue below holds metadata and the
-- official ncert.nic.in URLs only. The app links out to the official pages
-- and never downloads, proxies, caches or stores NCERT PDF content. Files
-- in curriculum_materials are the school's own, in its private tenant-docs
-- storage.
--
-- Tables
--   ncert_textbooks           reference catalogue (391 rows, retrieved
--                             2026-11-11). It is the same for every school, so
--                             it has NO institution_id: readable by
--                             `authenticated`, no client writes, nothing for
--                             anon. Rows are generated by
--                             scripts/ncert/build-migration.ts from
--                             scripts/ncert/ncert-catalogue.json; refresh it
--                             with a NEW migration (the generated block
--                             upserts on `code`), never by editing this file.
--                             `verified`: chapter 01 and chapter N PDFs
--                             answered 200 (English rows only; Hindi/Urdu
--                             rows were not checked).
--   subject_textbooks         a school's (grade, subject) -> an NCERT book or a
--                             custom book (title, publisher, optional https
--                             link). chapter_titles: the school's own chapter
--                             names ({"1": "..."}) because NCERT publishes no
--                             chapter titles as text.
--   curriculum_unit_chapters  one curriculum unit -> one chapter of a mapped
--                             book (grade/subject copied from the unit and
--                             bound to it in `with check`).
--   curriculum_materials      where an uploaded file sits (grade, subject,
--                             optional unit) and who sees it. The file itself
--                             is a documents row (entity_type
--                             'curriculum_material', entity_id = material id)
--                             in the private tenant-docs bucket, so the 0067
--                             upload flow, bucket and storage policies are
--                             reused as they are (10 MB cap, PDF/JPEG/PNG).
--
-- Visibility (curriculum_materials; L = owner, principal, admin; T = teacher
-- with a subject_assignments row for that (grade, subject))
--   class     staff of the school; students enrolled (active) in a section
--             of that grade that has the subject; their linked guardians
--             (read-only).
--   private   the uploader only; a student's file also to their linked
--             guardians (read-only). Never to classmates, never to staff.
--   suggested a student's private file the student offered to the class:
--             also visible to T and L, who approve (visibility becomes
--             'class', ownership stays the student's) or decline (the
--             declining reviewer still sees it until the student refiles).
--   delete    the uploader; T and L for class materials.
-- The documents rows of these files are exactly as visible as their
-- material (a restrictive policy narrows 0071's leader branch), and the
-- tenant-docs object policies delegate to documents RLS (0067), so storage
-- follows the same rule with no new storage policy.
--
-- Functions
--   app.my_taught_grade_subjects()  (definer, initPlan helper) (grade, subject)
--     pairs the caller teaches through subject_assignments.
--   app.my_studied_grade_subjects() (definer, initPlan helper) (grade, subject)
--     pairs of the active sections of app.my_student_ids() (own enrolment or
--     linked children) that have the subject assigned.
--   app.guard_curriculum_materials_update() (invoker trigger, no table reads):
--     identity columns frozen; a student owner may move/suggest only a private
--     file; a reviewer may only approve/decline a suggestion.
--   Reuses app.guard_resource_document_activate() (0131) for 'curriculum_material'
--   documents: pending -> active only when the uploaded object exists.
--   No public RPCs: every write is a plain table write under RLS.
--
-- Study studio (0138): study_materials.source_kind gains 'textbook' (a unit's
-- linked textbook chapter as the source; the AI never reads the PDF).

-- ---------------------------------------------------------------------------
-- RLS helpers
-- ---------------------------------------------------------------------------

create function app.my_taught_grade_subjects()
returns table (grade_id uuid, subject_id uuid)
language sql
stable
security definer
set search_path = ''
as $$
  select distinct cs.grade_id, sa.subject_id
  from public.subject_assignments sa
  join public.memberships m
    on m.staff_id = sa.teacher_id
   and m.institution_id = sa.institution_id
  join public.class_sections cs
    on cs.id = sa.class_section_id
   and cs.institution_id = sa.institution_id
  where m.user_id = app.current_user_id()
    and m.status = 'active';
$$;

revoke execute on function app.my_taught_grade_subjects() from public;
grant execute on function app.my_taught_grade_subjects() to authenticated;
comment on function app.my_taught_grade_subjects() is
  'RLS perf helper: (grade_id, subject_id) pairs the caller teaches via subject_assignments. Used as an uncorrelated `(grade_id, subject_id) in (select ...)` in the textbooks/curriculum materials policies.';

create function app.my_studied_grade_subjects()
returns table (grade_id uuid, subject_id uuid)
language sql
stable
security definer
set search_path = ''
as $$
  select distinct cs.grade_id, sa.subject_id
  from public.enrolments e
  join public.class_sections cs
    on cs.id = e.class_section_id
   and cs.institution_id = e.institution_id
  join public.subject_assignments sa
    on sa.class_section_id = cs.id
   and sa.institution_id = cs.institution_id
  where e.status = 'active'
    and e.student_id = any(array(select app.my_student_ids()));
$$;

revoke execute on function app.my_studied_grade_subjects() from public;
grant execute on function app.my_studied_grade_subjects() to authenticated;
comment on function app.my_studied_grade_subjects() is
  'RLS perf helper: (grade_id, subject_id) pairs studied in the active sections of app.my_student_ids() (own enrolment or linked children). Used as an uncorrelated `(grade_id, subject_id) in (select ...)` in the textbooks/curriculum materials policies.';

-- ---------------------------------------------------------------------------
-- ncert_textbooks — global reference catalogue (no institution_id)
-- ---------------------------------------------------------------------------

create table public.ncert_textbooks (
  code text primary key check (code ~ '^[a-z0-9]{3,12}$'),
  class_label text not null check (class_label ~ '^([1-9]|1[0-2]|11-12)$'),
  -- Null only for the "Class XI & XII combined" books.
  class_level smallint check (class_level between 1 and 12),
  subject text not null check (char_length(subject) between 1 and 80),
  title text not null check (char_length(title) between 1 and 160),
  medium text not null check (medium in ('English', 'Hindi', 'Urdu')),
  chapters_count smallint not null check (chapters_count between 1 and 99),
  book_url text not null check (book_url ~ '^https://ncert\.nic\.in/textbook\.php\?[a-z0-9]+=[0-9]+-[0-9]+$'),
  chapter_pdf_pattern text not null check (chapter_pdf_pattern ~ '^https://ncert\.nic\.in/textbook/pdf/[a-z0-9]+\{NN\}\.pdf$'),
  prelims_pdf text check (prelims_pdf is null or prelims_pdf ~ '^https://ncert\.nic\.in/textbook/pdf/[a-z0-9]+\.pdf$'),
  verified boolean not null default false,
  retrieved_on date not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint ncert_textbooks_class_check check ((class_label = '11-12') = (class_level is null))
);

create index ncert_textbooks_class_subject_idx on public.ncert_textbooks (class_level, medium);

create trigger set_updated_at
before update on public.ncert_textbooks
for each row execute function app.set_updated_at();

alter table public.ncert_textbooks enable row level security;

-- Same public catalogue for every school; no tenant data in it.
create policy ncert_textbooks_select on public.ncert_textbooks
  for select to authenticated
  using (true);

revoke all on public.ncert_textbooks from anon, authenticated;
grant select on public.ncert_textbooks to authenticated;
grant select, insert, update, delete on public.ncert_textbooks to service_role;

-- ---------------------------------------------------------------------------
-- subject_textbooks — a school's (grade, subject) -> textbook mapping
-- ---------------------------------------------------------------------------

create table public.subject_textbooks (
  id uuid primary key default gen_random_uuid(),
  institution_id uuid not null references public.institutions (id),
  grade_id uuid not null references public.grades (id),
  subject_id uuid not null references public.subjects (id),
  ncert_code text references public.ncert_textbooks (code),
  custom_title text check (custom_title is null or char_length(btrim(custom_title)) between 1 and 160),
  custom_publisher text check (custom_publisher is null or char_length(btrim(custom_publisher)) between 1 and 120),
  custom_url text check (
    custom_url is null
    or (char_length(custom_url) <= 2000 and custom_url ~ '^https://[^[:space:]/?#]+([/?#][^[:space:]]*)?$')
  ),
  custom_chapters smallint check (custom_chapters is null or custom_chapters between 1 and 99),
  chapter_titles jsonb not null default '{}'::jsonb check (jsonb_typeof(chapter_titles) = 'object' and pg_column_size(chapter_titles) <= 16384),
  position smallint not null default 0 check (position between 0 and 99),
  created_by uuid not null references public.profiles (id) default app.current_user_id(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- Composite-FK target for curriculum_unit_chapters.
  constraint subject_textbooks_id_institution_key unique (id, institution_id),
  constraint subject_textbooks_source_check check (
    (ncert_code is not null and custom_title is null and custom_publisher is null and custom_url is null and custom_chapters is null)
    or (ncert_code is null and custom_title is not null)
  )
);

create unique index subject_textbooks_ncert_unique_idx on public.subject_textbooks (institution_id, grade_id, subject_id, ncert_code) where ncert_code is not null;
create index subject_textbooks_grade_subject_idx on public.subject_textbooks (institution_id, grade_id, subject_id);
create index subject_textbooks_ncert_idx on public.subject_textbooks (ncert_code) where ncert_code is not null;

create trigger set_updated_at
before update on public.subject_textbooks
for each row execute function app.set_updated_at();

alter table public.subject_textbooks enable row level security;

create policy subject_textbooks_select on public.subject_textbooks
  for select to authenticated
  using (subject_textbooks.institution_id = any((select app.member_institutions())));

create policy subject_textbooks_insert on public.subject_textbooks
  for insert to authenticated
  with check (
    subject_textbooks.created_by = (select app.current_user_id())
    and (
      subject_textbooks.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
      or (
        subject_textbooks.institution_id = any((select app.my_institution_ids(array['teacher'])))
        and (subject_textbooks.grade_id, subject_textbooks.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
      )
    )
    and exists (select 1 from public.grades g where g.id = subject_textbooks.grade_id and g.institution_id = subject_textbooks.institution_id)
    and exists (select 1 from public.subjects s where s.id = subject_textbooks.subject_id and s.institution_id = subject_textbooks.institution_id)
  );

-- Column grant below: grade/subject/institution/created_by never change.
create policy subject_textbooks_update on public.subject_textbooks
  for update to authenticated
  using (
    subject_textbooks.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
    or (
      subject_textbooks.institution_id = any((select app.my_institution_ids(array['teacher'])))
      and (subject_textbooks.grade_id, subject_textbooks.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
    )
  )
  with check (
    subject_textbooks.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
    or (
      subject_textbooks.institution_id = any((select app.my_institution_ids(array['teacher'])))
      and (subject_textbooks.grade_id, subject_textbooks.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
    )
  );

create policy subject_textbooks_delete on public.subject_textbooks
  for delete to authenticated
  using (
    subject_textbooks.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
    or (
      subject_textbooks.institution_id = any((select app.my_institution_ids(array['teacher'])))
      and (subject_textbooks.grade_id, subject_textbooks.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
    )
  );

revoke all on public.subject_textbooks from anon, authenticated;
grant select, insert, delete on public.subject_textbooks to authenticated;
grant update (ncert_code, custom_title, custom_publisher, custom_url, custom_chapters, chapter_titles, position) on public.subject_textbooks to authenticated;
grant select, insert, update, delete on public.subject_textbooks to service_role;

-- ---------------------------------------------------------------------------
-- curriculum_unit_chapters — unit -> one chapter of a mapped book
-- ---------------------------------------------------------------------------

create table public.curriculum_unit_chapters (
  curriculum_unit_id uuid primary key references public.curriculum_units (id) on delete cascade,
  institution_id uuid not null references public.institutions (id),
  grade_id uuid not null references public.grades (id),
  subject_id uuid not null references public.subjects (id),
  subject_textbook_id uuid not null,
  chapter_no smallint not null check (chapter_no between 1 and 99),
  created_by uuid not null references public.profiles (id) default app.current_user_id(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint curriculum_unit_chapters_textbook_fk foreign key (subject_textbook_id, institution_id)
    references public.subject_textbooks (id, institution_id) on delete cascade
);

create index curriculum_unit_chapters_textbook_idx on public.curriculum_unit_chapters (subject_textbook_id);
create index curriculum_unit_chapters_grade_subject_idx on public.curriculum_unit_chapters (institution_id, grade_id, subject_id);

create trigger set_updated_at
before update on public.curriculum_unit_chapters
for each row execute function app.set_updated_at();

alter table public.curriculum_unit_chapters enable row level security;

create policy curriculum_unit_chapters_select on public.curriculum_unit_chapters
  for select to authenticated
  using (
    curriculum_unit_chapters.institution_id = any((select app.my_institution_ids(app.staff_roles())))
    or (curriculum_unit_chapters.grade_id, curriculum_unit_chapters.subject_id) in (select t.grade_id, t.subject_id from app.my_studied_grade_subjects() t)
  );

create policy curriculum_unit_chapters_insert on public.curriculum_unit_chapters
  for insert to authenticated
  with check (
    curriculum_unit_chapters.created_by = (select app.current_user_id())
    and (
      curriculum_unit_chapters.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
      or (
        curriculum_unit_chapters.institution_id = any((select app.my_institution_ids(array['teacher'])))
        and (curriculum_unit_chapters.grade_id, curriculum_unit_chapters.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
      )
    )
    and exists (
      select 1 from public.curriculum_units cu
      where cu.id = curriculum_unit_chapters.curriculum_unit_id
        and cu.institution_id = curriculum_unit_chapters.institution_id
        and cu.grade_id = curriculum_unit_chapters.grade_id
        and cu.subject_id = curriculum_unit_chapters.subject_id
    )
    and exists (
      select 1 from public.subject_textbooks st
      left join public.ncert_textbooks nt on nt.code = st.ncert_code
      where st.id = curriculum_unit_chapters.subject_textbook_id
        and st.institution_id = curriculum_unit_chapters.institution_id
        and st.grade_id = curriculum_unit_chapters.grade_id
        and st.subject_id = curriculum_unit_chapters.subject_id
        and curriculum_unit_chapters.chapter_no <= coalesce(nt.chapters_count, st.custom_chapters, 99)
    )
  );

-- Column grant below: only the book and chapter change.
create policy curriculum_unit_chapters_update on public.curriculum_unit_chapters
  for update to authenticated
  using (
    curriculum_unit_chapters.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
    or (
      curriculum_unit_chapters.institution_id = any((select app.my_institution_ids(array['teacher'])))
      and (curriculum_unit_chapters.grade_id, curriculum_unit_chapters.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
    )
  )
  with check (
    (
      curriculum_unit_chapters.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
      or (
        curriculum_unit_chapters.institution_id = any((select app.my_institution_ids(array['teacher'])))
        and (curriculum_unit_chapters.grade_id, curriculum_unit_chapters.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
      )
    )
    and exists (
      select 1 from public.subject_textbooks st
      left join public.ncert_textbooks nt on nt.code = st.ncert_code
      where st.id = curriculum_unit_chapters.subject_textbook_id
        and st.institution_id = curriculum_unit_chapters.institution_id
        and st.grade_id = curriculum_unit_chapters.grade_id
        and st.subject_id = curriculum_unit_chapters.subject_id
        and curriculum_unit_chapters.chapter_no <= coalesce(nt.chapters_count, st.custom_chapters, 99)
    )
  );

create policy curriculum_unit_chapters_delete on public.curriculum_unit_chapters
  for delete to authenticated
  using (
    curriculum_unit_chapters.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
    or (
      curriculum_unit_chapters.institution_id = any((select app.my_institution_ids(array['teacher'])))
      and (curriculum_unit_chapters.grade_id, curriculum_unit_chapters.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
    )
  );

revoke all on public.curriculum_unit_chapters from anon, authenticated;
grant select, insert, delete on public.curriculum_unit_chapters to authenticated;
grant update (subject_textbook_id, chapter_no) on public.curriculum_unit_chapters to authenticated;
grant select, insert, update, delete on public.curriculum_unit_chapters to service_role;

-- ---------------------------------------------------------------------------
-- curriculum_materials — the school's own uploaded files
-- ---------------------------------------------------------------------------

create table public.curriculum_materials (
  id uuid primary key default gen_random_uuid(),
  institution_id uuid not null references public.institutions (id),
  title text not null check (char_length(btrim(title)) between 1 and 160),
  grade_id uuid references public.grades (id),
  subject_id uuid references public.subjects (id),
  curriculum_unit_id uuid references public.curriculum_units (id) on delete set null,
  owner_kind text not null check (owner_kind in ('staff', 'student')),
  student_id uuid references public.students (id),
  visibility text not null default 'private' check (visibility in ('private', 'class')),
  suggestion text not null default 'none' check (suggestion in ('none', 'suggested', 'approved', 'declined')),
  reviewed_by uuid references public.profiles (id),
  reviewed_at timestamptz,
  created_by uuid not null references public.profiles (id) default app.current_user_id(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint curriculum_materials_owner_check check ((owner_kind = 'student') = (student_id is not null)),
  -- Grade and subject are set together ("unfiled" = both null: a chat upload
  -- waiting for its place); a unit needs both.
  constraint curriculum_materials_target_check check ((grade_id is null) = (subject_id is null) and (curriculum_unit_id is null or subject_id is not null)),
  constraint curriculum_materials_class_check check (visibility = 'private' or subject_id is not null),
  -- A student's file reaches the class only through an approved suggestion.
  constraint curriculum_materials_student_class_check check (owner_kind = 'staff' or visibility = 'private' or suggestion = 'approved'),
  constraint curriculum_materials_suggestion_target_check check (suggestion in ('none', 'declined') or (owner_kind = 'student' and subject_id is not null))
);

create index curriculum_materials_grade_subject_idx on public.curriculum_materials (institution_id, grade_id, subject_id);
create index curriculum_materials_unit_idx on public.curriculum_materials (curriculum_unit_id) where curriculum_unit_id is not null;
create index curriculum_materials_created_by_idx on public.curriculum_materials (created_by);
create index curriculum_materials_student_idx on public.curriculum_materials (student_id) where student_id is not null;

create trigger set_updated_at
before update on public.curriculum_materials
for each row execute function app.set_updated_at();

-- Invoker, plpgsql, no table reads (DBT-45-safe, 0067 guard shape): the
-- column grant allows title/target/visibility/suggestion; this decides who
-- may change which. Service role / postgres bypass (lesson 5).
create function app.guard_curriculum_materials_update()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_me uuid := app.current_user_id();
  v_moved boolean;
begin
  if coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '') = 'service_role'
    or session_user = 'postgres'
  then
    return new;
  end if;

  if new.institution_id is distinct from old.institution_id
    or new.owner_kind is distinct from old.owner_kind
    or new.student_id is distinct from old.student_id
    or new.created_by is distinct from old.created_by
  then
    raise exception 'code:forbidden' using detail = 'institution_id, owner_kind, student_id, created_by never change';
  end if;

  v_moved := new.title is distinct from old.title
    or new.grade_id is distinct from old.grade_id
    or new.subject_id is distinct from old.subject_id
    or new.curriculum_unit_id is distinct from old.curriculum_unit_id;

  if old.created_by = v_me and old.owner_kind = 'student' then
    -- A student files and suggests their own private file; sharing is the school's call.
    if new.visibility is distinct from old.visibility then
      raise exception 'code:forbidden' using detail = 'a student cannot change who sees a file';
    end if;
    if new.suggestion is distinct from old.suggestion
      and not (new.suggestion in ('none', 'suggested') and old.suggestion in ('none', 'suggested', 'declined'))
    then
      raise exception 'code:invalid_state' using detail = 'a student may only suggest or withdraw a suggestion';
    end if;
    if v_moved and (old.visibility = 'class' or old.suggestion = 'suggested') then
      raise exception 'code:invalid_state' using detail = 'a shared or suggested file cannot be moved';
    end if;
    new.reviewed_by := old.reviewed_by;
    new.reviewed_at := old.reviewed_at;
    return new;
  end if;

  if old.created_by = v_me then
    if new.suggestion is distinct from old.suggestion then
      raise exception 'code:forbidden' using detail = 'staff files have no suggestion';
    end if;
    return new;
  end if;

  -- Anyone else reached this through curriculum_materials_update_review
  -- (subject teacher or leader): decide a pending suggestion, nothing more.
  if old.suggestion <> 'suggested' or new.suggestion not in ('approved', 'declined') then
    raise exception 'code:invalid_state' using detail = 'only a suggested file can be approved or declined';
  end if;
  if v_moved then
    raise exception 'code:forbidden' using detail = 'a reviewer cannot move or rename a file';
  end if;
  -- Approval copies visibility; ownership stays the student's.
  new.visibility := case when new.suggestion = 'approved' then 'class' else old.visibility end;
  new.reviewed_by := v_me;
  new.reviewed_at := now();
  return new;
end;
$$;

revoke execute on function app.guard_curriculum_materials_update() from public;

create trigger guard_curriculum_materials_update
before update on public.curriculum_materials
for each row execute function app.guard_curriculum_materials_update();

alter table public.curriculum_materials enable row level security;

create policy curriculum_materials_select on public.curriculum_materials
  for select to authenticated
  using (
    curriculum_materials.created_by = (select app.current_user_id())
    or (
      curriculum_materials.visibility = 'class'
      and (
        curriculum_materials.institution_id = any((select app.my_institution_ids(app.staff_roles())))
        or (curriculum_materials.grade_id, curriculum_materials.subject_id) in (select t.grade_id, t.subject_id from app.my_studied_grade_subjects() t)
      )
    )
    or (
      curriculum_materials.owner_kind = 'student'
      and curriculum_materials.student_id = any((select app.my_student_ids()))
    )
    or (
      curriculum_materials.suggestion = 'suggested'
      and (
        curriculum_materials.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
        or (
          curriculum_materials.institution_id = any((select app.my_institution_ids(array['teacher'])))
          and (curriculum_materials.grade_id, curriculum_materials.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
        )
      )
    )
    -- The reviewer keeps sight of a file they declined (an UPDATE's new row
    -- must stay visible to its author); it is gone once the student refiles it.
    or (
      curriculum_materials.suggestion = 'declined'
      and curriculum_materials.reviewed_by = (select app.current_user_id())
    )
  );

create policy curriculum_materials_insert on public.curriculum_materials
  for insert to authenticated
  with check (
    curriculum_materials.created_by = (select app.current_user_id())
    and curriculum_materials.suggestion = 'none'
    and curriculum_materials.reviewed_by is null
    and curriculum_materials.reviewed_at is null
    and (
      curriculum_materials.grade_id is null
      or exists (select 1 from public.grades g where g.id = curriculum_materials.grade_id and g.institution_id = curriculum_materials.institution_id)
    )
    and (
      curriculum_materials.subject_id is null
      or exists (select 1 from public.subjects s where s.id = curriculum_materials.subject_id and s.institution_id = curriculum_materials.institution_id)
    )
    and (
      curriculum_materials.curriculum_unit_id is null
      or exists (
        select 1 from public.curriculum_units cu
        where cu.id = curriculum_materials.curriculum_unit_id
          and cu.institution_id = curriculum_materials.institution_id
          and cu.grade_id = curriculum_materials.grade_id
          and cu.subject_id = curriculum_materials.subject_id
      )
    )
    and (
      (
        curriculum_materials.owner_kind = 'staff'
        and (
          curriculum_materials.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
          or (
            curriculum_materials.institution_id = any((select app.my_institution_ids(array['teacher'])))
            and (
              curriculum_materials.visibility = 'private'
              or (curriculum_materials.grade_id, curriculum_materials.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
            )
          )
        )
      )
      or (
        curriculum_materials.owner_kind = 'student'
        and curriculum_materials.visibility = 'private'
        and exists (
          select 1 from public.memberships m
          where m.user_id = (select app.current_user_id())
            and m.institution_id = curriculum_materials.institution_id
            and m.role = 'student'
            and m.status = 'active'
            and m.student_id = curriculum_materials.student_id
        )
        and (
          curriculum_materials.subject_id is null
          or (curriculum_materials.grade_id, curriculum_materials.subject_id) in (select t.grade_id, t.subject_id from app.my_studied_grade_subjects() t)
        )
      )
    )
  );

-- The uploader files/renames their own; the guard trigger narrows it further.
create policy curriculum_materials_update_own on public.curriculum_materials
  for update to authenticated
  using (curriculum_materials.created_by = (select app.current_user_id()))
  with check (
    curriculum_materials.created_by = (select app.current_user_id())
    and (
      curriculum_materials.grade_id is null
      or exists (select 1 from public.grades g where g.id = curriculum_materials.grade_id and g.institution_id = curriculum_materials.institution_id)
    )
    and (
      curriculum_materials.subject_id is null
      or exists (select 1 from public.subjects s where s.id = curriculum_materials.subject_id and s.institution_id = curriculum_materials.institution_id)
    )
    and (
      curriculum_materials.curriculum_unit_id is null
      or exists (
        select 1 from public.curriculum_units cu
        where cu.id = curriculum_materials.curriculum_unit_id
          and cu.institution_id = curriculum_materials.institution_id
          and cu.grade_id = curriculum_materials.grade_id
          and cu.subject_id = curriculum_materials.subject_id
      )
    )
    and (
      (
        curriculum_materials.owner_kind = 'staff'
        and (
          curriculum_materials.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
          or (
            curriculum_materials.institution_id = any((select app.my_institution_ids(array['teacher'])))
            and (
              curriculum_materials.visibility = 'private'
              or (curriculum_materials.grade_id, curriculum_materials.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
            )
          )
        )
      )
      or (
        curriculum_materials.owner_kind = 'student'
        and curriculum_materials.institution_id = any((select app.my_institution_ids(array['student'])))
        and (
          curriculum_materials.subject_id is null
          or (curriculum_materials.grade_id, curriculum_materials.subject_id) in (select t.grade_id, t.subject_id from app.my_studied_grade_subjects() t)
        )
      )
    )
  );

-- The subject's teacher or a leader approves/declines a suggestion.
create policy curriculum_materials_update_review on public.curriculum_materials
  for update to authenticated
  using (
    curriculum_materials.suggestion = 'suggested'
    and (
      curriculum_materials.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
      or (
        curriculum_materials.institution_id = any((select app.my_institution_ids(array['teacher'])))
        and (curriculum_materials.grade_id, curriculum_materials.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
      )
    )
  )
  with check (
    curriculum_materials.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
    or (
      curriculum_materials.institution_id = any((select app.my_institution_ids(array['teacher'])))
      and (curriculum_materials.grade_id, curriculum_materials.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
    )
  );

create policy curriculum_materials_delete on public.curriculum_materials
  for delete to authenticated
  using (
    curriculum_materials.created_by = (select app.current_user_id())
    or (
      curriculum_materials.visibility = 'class'
      and (
        curriculum_materials.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
        or (
          curriculum_materials.institution_id = any((select app.my_institution_ids(array['teacher'])))
          and (curriculum_materials.grade_id, curriculum_materials.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
        )
      )
    )
  );

revoke all on public.curriculum_materials from anon, authenticated;
grant select, insert, delete on public.curriculum_materials to authenticated;
grant update (title, grade_id, subject_id, curriculum_unit_id, visibility, suggestion) on public.curriculum_materials to authenticated;
grant select, insert, update, delete on public.curriculum_materials to service_role;

-- ---------------------------------------------------------------------------
-- documents: entity type `curriculum_material` (list = 0131's + it).
-- Additive policies only; 0071/0077/0131 policies are untouched.
-- ---------------------------------------------------------------------------

alter table public.documents drop constraint documents_entity_type_check;
alter table public.documents
  add constraint documents_entity_type_check
  check (entity_type in ('student', 'staff', 'application', 'submission', 'report', 'resource', 'curriculum_material'));

-- One live file per material (a retry makes a new material).
create unique index documents_one_curriculum_material_idx on public.documents (entity_id)
  where entity_type = 'curriculum_material' and status in ('pending', 'active');

-- Visible exactly when the material is (curriculum_materials RLS composes).
create policy documents_select_curriculum_material on public.documents
  for select to authenticated
  using (
    documents.entity_type = 'curriculum_material'
    and exists (
      select 1 from public.curriculum_materials m
      where m.id = documents.entity_id and m.institution_id = documents.institution_id
    )
  );

-- Narrows 0071's leader branch: a student's private file stays private.
create policy documents_curriculum_material_read_guard on public.documents
  as restrictive
  for select to authenticated
  using (
    documents.entity_type <> 'curriculum_material'
    or exists (
      select 1 from public.curriculum_materials m
      where m.id = documents.entity_id and m.institution_id = documents.institution_id
    )
  );

create policy documents_insert_curriculum_material on public.documents
  for insert to authenticated
  with check (
    documents.entity_type = 'curriculum_material'
    and documents.created_by = (select app.current_user_id())
    and documents.status = 'pending'
    and documents.path like documents.institution_id::text || '/curriculum_material/' || documents.entity_id::text || '/%'
  );

-- Only the material's own uploader attaches its file, and only PDF/JPEG/PNG
-- (0071's leader insert branch has no such binding).
create policy documents_curriculum_material_write_guard on public.documents
  as restrictive
  for insert to authenticated
  with check (
    documents.entity_type <> 'curriculum_material'
    or (
      documents.mime in ('application/pdf', 'image/jpeg', 'image/png')
      and exists (
        select 1 from public.curriculum_materials m
        where m.id = documents.entity_id
          and m.institution_id = documents.institution_id
          and m.created_by = (select app.current_user_id())
      )
    )
  );

-- Confirm (uploader) and delete (uploader; subject teacher / leader for class files).
create policy documents_update_curriculum_material on public.documents
  for update to authenticated
  using (
    documents.entity_type = 'curriculum_material'
    and exists (
      select 1 from public.curriculum_materials m
      where m.id = documents.entity_id
        and m.institution_id = documents.institution_id
        and (
          m.created_by = (select app.current_user_id())
          or (
            m.visibility = 'class'
            and (
              m.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
              or (
                m.institution_id = any((select app.my_institution_ids(array['teacher'])))
                and (m.grade_id, m.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
              )
            )
          )
        )
    )
  )
  with check (
    documents.entity_type = 'curriculum_material'
    and exists (
      select 1 from public.curriculum_materials m
      where m.id = documents.entity_id
        and m.institution_id = documents.institution_id
        and (
          m.created_by = (select app.current_user_id())
          or (
            m.visibility = 'class'
            and (
              m.institution_id = any((select app.my_institution_ids(array['owner', 'principal', 'admin'])))
              or (
                m.institution_id = any((select app.my_institution_ids(array['teacher'])))
                and (m.grade_id, m.subject_id) in (select t.grade_id, t.subject_id from app.my_taught_grade_subjects() t)
              )
            )
          )
        )
    )
  );

-- Same SQL-side "object exists" check as resources (0131 function, reused).
create trigger guard_curriculum_material_document_activate
before update on public.documents
for each row
when (old.entity_type = 'curriculum_material' and old.status = 'pending' and new.status = 'active')
execute function app.guard_resource_document_activate();

-- ---------------------------------------------------------------------------
-- study_materials (0138): textbook-chapter source
-- ---------------------------------------------------------------------------

alter table public.study_materials drop constraint study_materials_source_kind_check;
alter table public.study_materials
  add constraint study_materials_source_kind_check
  check (source_kind in ('unit', 'paste', 'resource', 'lesson_plan', 'textbook'));

